INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (1, N'url.url_length', N'url', N'URL Length', N'Flags unusually long or short URLs, a common phishing-link obfuscation signal.', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (2, N'url.https_check', N'url', N'HTTPS', N'Flags URLs that don''t use HTTPS (unencrypted traffic).', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (3, N'url.ssl_certificate', N'url', N'SSL Certificate', N'Performs a real TLS handshake and flags invalid, expired, or unverifiable certificates.', N'high', 1, 3, N'2026-08-11 16:46:56.353000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (4, N'url.ip_address', N'url', N'IP Address Host', N'Flags URLs that use a raw IP address instead of a domain name.', N'high', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (5, N'url.suspicious_keywords', N'url', N'Suspicious Keywords', N'Flags login/verify/bank/wallet/paypal-style phishing lure keywords in the URL.', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (6, N'url.special_characters', N'url', N'Special Characters', N'Flags ''@'' in the host, excessive ''%'' encoding, repeated ''-''/''_'', and smuggled ''//''.', N'high', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (7, N'url.subdomains', N'url', N'Subdomains', N'Flags unusually deep subdomain chains, a common brand-impersonation tactic.', N'high', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (8, N'url.typosquatting', N'url', N'Typosquatting', N'Flags domains within a small edit distance of a well-known brand domain.', N'critical', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (9, N'url.domain_age', N'url', N'Domain Age', N'Looks up domain registration age via RDAP; recently-registered domains are riskier.', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (10, N'url.blacklist_check', N'url', N'Blacklist', N'Checks the domain against CyberShield''s own blacklist table.', N'critical', 1, 5, N'2026-07-23 16:18:41.373000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (11, N'url.redirect_check', N'url', N'Redirect Chain', N'Follows redirects (SSRF-safe) and flags long chains or a cross-domain final destination.', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (12, N'email.sender_analysis', N'email', N'Sender Analysis', N'Flags missing/malformed sender addresses and free-provider addresses claiming to be an organization.', N'high', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (13, N'email.display_name_impersonation', N'email', N'Display Name Impersonation', N'Flags a display name naming a specific known brand whose sender domain doesn''t match.', N'critical', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (14, N'email.subject_analysis', N'email', N'Subject Analysis', N'Flags phishing-lure phrases in the subject line.', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (15, N'email.greeting_analysis', N'email', N'Greeting Analysis', N'Flags generic greetings (''Dear Customer'') instead of a real name.', N'low', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (16, N'email.urgency_detection', N'email', N'Urgency Detection', N'Flags pressure language (''act now'', ''within 24 hours'').', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (17, N'email.threat_language', N'email', N'Threat Language', N'Flags consequence language (''account suspension'', ''security breach'').', N'medium', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (18, N'email.link_analysis', N'email', N'Link Analysis', N'Classifies every link in the email via the URL scanner''s quick_classify.', N'critical', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (19, N'email.attachment_analysis', N'email', N'Attachment Analysis', N'Flags dangerous extensions and double-extension disguises.', N'critical', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (20, N'email.html_analysis', N'email', N'HTML Analysis', N'Flags embedded scripts/forms, hidden elements, and obfuscated encoding.', N'critical', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (21, N'email.grammar_heuristics', N'email', N'Grammar Heuristics', N'Light-touch, low-weight signals (repeated punctuation, ALL-CAPS ratio) — deliberately capped.', N'info', 1, 1, N'2026-07-23 16:16:26.740000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (22, N'url.whitelist_check', N'url', N'Verified Safe List', N'Grants trust reinforcement for domains on CyberShield''s curated high-reputation brand list.', N'info', 1, 1, N'2026-10-01 09:50:36.650000');
INSERT INTO [detection_rules] ([id], [key], [category], [label], [description], [severity], [enabled], [version], [updated_at]) VALUES (23, N'url.external_threat_intel', N'url', N'Global Threat Intelligence', N'Checks the URL/domain against VirusTotal and URLhaus threat feeds for confirmed malicious activity.', N'critical', 1, 1, N'2026-10-01 09:50:36.650000');
INSERT INTO [blacklist_entries] ([id], [domain], [reason], [added_by_user_id], [created_at], [enabled]) VALUES (3, N'phase9-verify-phish.example', N'Phase 9 browser verification', NULL, N'2026-07-25 14:06:02.607000', 1);
